INSERT INTO `tbl_module_content` (`id`, `school_id`, `module_key`, `content`, `is_published`, `created_at`, `updated_at`) VALUES (304, 9, 'home', '{\"tagline\":\"\",\"subText\":\"\",\"heroBgType\":\"video\",\"heroBanners\":[],\"schoolNameColor\":\"\",\"schoolNameFont\":\"\",\"taglineColor\":\"\",\"subTextColor\":\"\",\"showAnnouncementTicker\":true,\"introHeading\":\"Highlight of MCS\",\"introHeadingColor\":\"\",\"introHeadingFont\":\"\",\"introHeadingItalic\":true,\"introDescription\":\"<p><strong class=\\\"ql-font-playfair\\\">Real Madrid Club de Fútbol</strong><span class=\\\"ql-font-playfair\\\">, founded on </span><strong class=\\\"ql-font-playfair\\\">6 March 1902</strong><span class=\\\"ql-font-playfair\\\"> in Madrid, Spain, is widely regarded as one of the greatest and most successful football clubs in the history of the sport. Originally established as </span><strong class=\\\"ql-font-playfair\\\">Madrid Football Club</strong><span class=\\\"ql-font-playfair\\\">, the institution quickly gained recognition for its competitive spirit and commitment to excellence. In </span><strong class=\\\"ql-font-playfair\\\">1920</strong><span class=\\\"ql-font-playfair\\\">, King Alfonso XIII granted the club the honorary title </span><strong class=\\\"ql-font-playfair\\\">&quot;Real&quot;</strong><span class=\\\"ql-font-playfair\\\">, meaning &quot;Royal,&quot; allowing it to adopt the royal crown in its crest and officially become </span><strong class=\\\"ql-font-playfair\\\">Real Madrid Club de Fútbol</strong><span class=\\\"ql-font-playfair\\\">. The club was also one of the founding members of Spain&#39;s top football division, </span><strong class=\\\"ql-font-playfair\\\">La Liga</strong><span class=\\\"ql-font-playfair\\\">, in 1929 and has remained in the league ever since, never suffering relegation. Over the decades, Real Madrid has become a symbol of prestige, professionalism, and sporting excellence, earning a passionate fan base that spans every continent.</span><strong class=\\\"ql-font-playfair\\\">Real Madrid Club de Fútbol</strong><span class=\\\"ql-font-playfair\\\">, founded on </span><strong class=\\\"ql-font-playfair\\\">6 March 1902</strong><span class=\\\"ql-font-playfair\\\"> in Madrid, Spain, is widely regarded as one of the greatest and most successful football clubs in the history of the sport. Originally established as </span><strong class=\\\"ql-font-playfair\\\">Madrid Football Club</strong><span class=\\\"ql-font-playfair\\\">, the institution quickly gained recognition for its competitive spirit and commitment to excellence. In </span><strong class=\\\"ql-font-playfair\\\">1920</strong><span class=\\\"ql-font-playfair\\\">, King Alfonso XIII granted the club the honorary title </span><strong class=\\\"ql-font-playfair\\\">&quot;Real&quot;</strong><span class=\\\"ql-font-playfair\\\">, meaning &quot;Royal,&quot; allowing it to adopt the royal crown in its crest and officially become </span><strong class=\\\"ql-font-playfair\\\">Real Madrid Club de Fútbol</strong><span class=\\\"ql-font-playfair\\\">. The club was also one of the founding members of Spain&#39;s top football division, </span><strong class=\\\"ql-font-playfair\\\">La Liga</strong><span class=\\\"ql-font-playfair\\\">, in 1929 and has remained in the league ever since, never suffering relegation. Over the decades, Real Madrid has become a symbol of prestige, professionalism, and sporting excellence, earning a passionate fan base that spans every continent.</span></p>\",\"introImage1\":\"https://res.cloudinary.com/psl2kuge/image/upload/v1789492382/school-saas/content/school-9/uh5am7cxu41podjcc1lk.jpg\",\"introImage2\":\"https://res.cloudinary.com/psl2kuge/image/upload/v1789492395/school-saas/content/school-9/juuqae0d7oufyrsy4fle.jpg\",\"tourHeading\":\"School Tour\",\"tourYoutubeUrl\":\"\",\"campusHeading\":\"Campus Glimpses\",\"campusHeadingColor\":\"\",\"campusHeadingFont\":\"\",\"campusSubtext\":\"\",\"campusImages\":[],\"testimonialsHeading\":\"What People Say About Us\",\"testimonialsHeadingColor\":\"\",\"testimonialsHeadingFont\":\"montserrat\",\"testimonials\":[]}', 1, '2026-07-07 14:58:09', '2026-09-15 11:43:26');
INSERT INTO `tbl_module_content` (`id`, `school_id`, `module_key`, `content`, `is_published`, `created_at`, `updated_at`) VALUES (309, 9, 'about', '{\"visionMissionItems\":[{\"id\":\"vm‑1783456679394\",\"heading\":\"Our Vision\",\"text\":\"<p><span class=\\\"ql-font-playfair\\\" style=\\\"color: rgb(15, 23, 42); background-color: rgb(255, 255, 255);\\\">To be a center for excellence in education which, in keeping with the rich heritage of india.Will stress on the simultaneous development of body, mind and spirit and endeavor to create eat apples</span></p>\",\"headingItalic\":false},{\"id\":\"vm‑1783456703455\",\"heading\":\"Our Mission\",\"text\":\"<p><span class=\\\"ql-font-playfair\\\" style=\\\"color: rgb(15, 23, 42);\\\">We wish to create a society that is globally competitive, culturally emboldened and possessively consistent. We appreciate Cooperative Compatibilities</span></p>\",\"headingItalic\":false},{\"id\":\"vm‑1784625766869\",\"heading\":\"Motto\",\"text\":\"<p><span class=\\\"ql-font-playfair\\\" style=\\\"background-color: rgb(255, 255, 255); color: rgb(15, 23, 42);\\\">To be a center for excellence in education which, in keeping with the rich heritage of india.Will stress on the simultaneous development of body, mind and spirit and endeavor to create </span></p>\"},{\"id\":\"vm‑1783662672084\",\"heading\":\"Academic Excellence\",\"text\":\"<p><span class=\\\"ql-font-playfair\\\" style=\\\"color: rgb(15, 23, 42);\\\">We are committed to delivering quality education that inspires curiosity, critical thinking, and a passion for lifelong learning, enabling every student to achieve their highest potential.</span></p>\"},{\"id\":\"vm‑1783662696727\",\"heading\":\"Values & Character\",\"text\":\"<p><span class=\\\"ql-font-playfair\\\" style=\\\"color: rgb(15, 23, 42);\\\">We nurture integrity, discipline, empathy, and respect, helping students develop strong moral values and become responsible, compassionate individuals.</span></p>\"}],\"history\":\"<p><strong>Real Madrid Club de Fútbol</strong>, founded on <strong>6 March 1902</strong> in Madrid, Spain, is widely regarded as one of the greatest and most successful football clubs in the history of the sport. Originally established as <strong>Madrid Football Club</strong>, the institution quickly gained recognition for its competitive spirit and commitment to excellence. In <strong>1920</strong>, King Alfonso XIII granted the club the honorary title <strong>&quot;Real&quot;</strong>, meaning &quot;Royal,&quot; allowing it to adopt the royal crown in its crest and officially become <strong>Real Madrid Club de Fútbol</strong>. The club was also one of the founding members of Spain&#39;s top football division, <strong>La Liga</strong>, in 1929 and has remained in the league ever since, never suffering relegation. Over the decades, Real Madrid has become a symbol of prestige, professionalism, and sporting excellence, earning a passionate fan base that spans every continent.</p><p>The club&#39;s rise to global dominance began during the presidency of <strong>Santiago Bernabéu</strong>, whose vision transformed Real Madrid into an international football powerhouse. Under his leadership, the iconic <strong>Santiago Bernabéu Stadium</strong> was built, and the club attracted legendary players such as <strong>Alfredo Di Stéfano</strong>, <strong>Ferenc Puskás</strong>, and <strong>Francisco Gento</strong>. During the 1950s, Real Madrid achieved an unprecedented feat by winning the first <strong>five consecutive European Cups</strong> (1956–1960), establishing itself as the dominant force in European football. This winning tradition continued through every generation, with world‑class stars including <strong>Raúl González</strong>, <strong>Zinedine Zidane</strong>, <strong>Iker Casillas</strong>, <strong>Cristiano Ronaldo</strong>, <strong>Sergio Ramos</strong>, <strong>Luka Modrić</strong>, and many others contributing to the club&#39;s remarkable success. Real Madrid&#39;s philosophy has always been built on attacking football, relentless ambition, and the pursuit of excellence, making it one of the most admired and respected institutions in world sport.</p><p class=\\\"ql-align-justify\\\">Today, Real Madrid is recognized not only for its extraordinary list of trophies but also for its global influence on football and popular culture. The club has won numerous <strong>La Liga</strong> championships, <strong>Copa del Rey</strong> titles, and a record number of <strong>UEFA Champions League</strong> trophies, cementing its reputation as the most successful club in European football. Beyond success on the pitch, Real Madrid is admired for its world‑class youth academy, commitment to developing future talent, modern infrastructure, and worldwide community initiatives. Millions of supporters proudly wear the famous white jersey, inspired by the club&#39;s values of determination, teamwork, discipline, and excellence. Guided by its timeless motto, <strong>&quot;¡Hala Madrid y Nada Más!&quot;</strong> (&quot;Go Madrid and Nothing Else!&quot;), Real Madrid continues to inspire generations of football fans and remains a benchmark of sporting greatness, innovation, and enduring success.</p>\",\"historyImage\":\"https://res.cloudinary.com/psl2kuge/image/upload/v1789471501/school-saas/content/school-9/l86ymccjputt2zgz3elt.jpg\",\"historyGalleryImages\":[\"https://res.cloudinary.com/dllspz9pv/image/upload/v1784969846/school-saas/content/rjyfotwtd9fehgimq1fd.jpg\",\"https://res.cloudinary.com/dllspz9pv/image/upload/v1784970202/school-saas/content/rdzi0cnyszb2rioqippo.jpg\",\"https://res.cloudinary.com/dllspz9pv/image/upload/v1784970206/school-saas/content/ehjqjgbvqwuai1wytswt.jpg\",\"https://res.cloudinary.com/dllspz9pv/image/upload/v1786788418/school-saas/content/nhtibtgm2afre5zrqs4y.jpg\"],\"historyHeading\":\"\",\"historyHeadingColor\":\"\",\"historyHeadingFont\":\"\",\"historyHeadingItalic\":false,\"foundedYear\":\"2008\",\"leadershipMembers\":[{\"id\":\"leader‑1783456959473\",\"photo\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1784970293/school-saas/content/tbxbup1ytn3ogxw4xozc.jpg\",\"name\":\"Florentino Perez\",\"designation\":\"President \",\"message\":\"<p>At Real Madrid School, we believe that education, like football, demands dedication, teamwork, and an unwavering commitment to excellence. Just as our players give everything on the pitch, our students are inspired to give their best in every classroom, every day. We are not just building great students — we are building champions of life. The values that have made Real Madrid the greatest club in the world — resilience, ambition, and a relentless pursuit of greatness — are the same values we instill in every child who walks through our doors.</p><p class=\\\"ql-align-justify\\\">Real Madrid School is more than an institution — it is a promise. A promise that every student, regardless of where they come from, will be given the tools, the guidance, and the inspiration to reach their fullest potential. We have built a world where academic excellence and human values go hand in hand, where teachers are mentors, and where every student is seen, heard, and believed in. Together, we are writing the next great chapter — not on a football pitch, but in the classrooms, laboratories, and hearts of the next generation.</p>\"},{\"id\":\"leader‑1784625834426\",\"photo\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1784979615/school-saas/content/kzxtpniau8ouyjfppnj7.jpg\",\"name\":\"Alfredo di Stefano\",\"designation\":\"Chairman\",\"message\":\"<p>In my years on the field, I learned that true greatness is never achieved alone. It is built through discipline, passion, and the courage to keep going when things get difficult. I have seen players transform themselves through sheer determination — boys who arrived with raw talent and left as legends. At Real Madrid School, we carry that same spirit into education, where every child is encouraged to discover their potential, push their boundaries, and rise beyond what they ever thought possible. The classroom is our pitch, and every lesson is a match we play together.</p><p>What I want every student at Real Madrid School to understand is this — the greatest victory in life is not a trophy, it is the person you become in pursuit of it. We teach our students not just mathematics and science, but courage, integrity, and the profound joy of learning. When a child leaves these halls, I want them to carry with them not just knowledge, but character — the kind that makes a difference in the world. That is the Real Madrid way, and that will always be our way.</p>\",\"nameColor\":\"\",\"nameFont\":\"\",\"designationColor\":\"\",\"designationFont\":\"\"}],\"leadershipHeading\":\"\",\"leadershipHeadingColor\":\"\",\"leadershipHeadingFont\":\"\",\"leadershipHeadingItalic\":false,\"values\":[{\"title\":\"Holistic Development\",\"description\":\"<p><span class=\\\"ql-font-playfair\\\">Education extends beyond the classroom. We encourage students to explore their talents in sports, arts, leadership, and co‑curricular activities, helping them develop into well‑rounded individuals who are physically, emotionally, intellectually, and socially confident.</span></p>\"},{\"title\":\"Compassion & Social Responsibility\",\"description\":\"<p><span class=\\\"ql-font-playfair\\\">We inspire students to be empathetic, inclusive, and committed to serving society. By fostering kindness, respect for diversity, and environmental awareness, we prepare young minds to contribute positively to their communities and the world.</span></p>\"},{\"title\":\"Holistic Development\",\"description\":\"<p><span class=\\\"ql-font-playfair\\\">Education extends beyond the classroom. We encourage students to explore their talents in sports, arts, leadership, and co‑curricular activities, helping them develop into well‑rounded individuals who are physically, emotionally, intellectually, and socially confident.</span></p>\"}],\"affiliationsHeading\":\"\",\"affiliationsHeadingColor\":\"\",\"affiliationsHeadingFont\":\"\",\"affiliationsHeadingItalic\":false,\"affiliations\":[{\"id\":\"aff‑1784722711744\",\"image\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1784798346/school-saas/content/w9hdhxpj8kuvfug2utwt.jpg\",\"heading\":\"ISO\",\"link\":\"https://www.youtube.com/\"},{\"id\":\"aff‑1784715264811\",\"image\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1784715275/school-saas/content/n61ex5x3dafb8bdn6wz4.jpg\",\"heading\":\"Swayam Certified\"},{\"id\":\"aff‑1784715128105\",\"image\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1784715142/school-saas/content/mejibzhhkahhr1uoo14b.jpg\",\"heading\":\"NCC Certified\"},{\"id\":\"aff‑1784714476536\",\"image\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1784715024/school-saas/content/zw0af6et4kqtubb6wube.jpg\",\"heading\":\"CBSE Affiliation\"}],\"awardsHeading\":\"Awards and Recognitions \",\"awardsHeadingColor\":\"\",\"awardsHeadingFont\":\"\",\"awardsHeadingItalic\":false,\"awards\":[{\"id\":\"awd‑1786955550854\",\"image\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1786955564/school-saas/content/ykti2blio6bkf8veqcyv.jpg\",\"heading\":\"N BV\",\"name\":\"HG\",\"designation\":\"HTG\"},{\"id\":\"awd‑1784721568432\",\"image\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1784971043/school-saas/content/gpg5kn2otil04agarolg.jpg\",\"heading\":\"Educational Reformer of the year\",\"name\":\"Naveen Jain\",\"designation\":\"Head of Department\"},{\"id\":\"awd‑1784721424112\",\"image\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1784970845/school-saas/content/rt3p9rhnsymsxhyvyfb2.jpg\",\"heading\":\"Most Socially Active Principal\",\"name\":\"Amit Soni\",\"designation\":\"HOD\"},{\"id\":\"awd‑1784795925345\",\"image\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1784971007/school-saas/content/ojwk6mahlgznwizdwx05.jpg\",\"heading\":\"Best Director Award\",\"designation\":\"Director\",\"name\":\"Shantanu Sharma\"}],\"bannerImage\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783594039/school-saas/content/d9ghq3mf1sbem8c3vmtd.jpg\"}', 1, '2026-07-07 15:08:18', '2026-09-15 05:55:07');
INSERT INTO `tbl_module_content` (`id`, `school_id`, `module_key`, `content`, `is_published`, `created_at`, `updated_at`) VALUES (333, 9, 'infrastructure', '{\"categories\":[{\"id\":\"cat‑1783494846570\",\"slug\":\"computer‑labs\",\"name\":\"Computer Labs\",\"banner\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783663406/school-saas/content/voxnnskiwsuufeoo9d7f.jpg\",\"heading\":\"Computer Laboratory\",\"description\":\"<p><span class=\\\"ql-font-playfair\\\">At Malviya Convent School, our Smart Classrooms are designed to transform traditional teaching into an engaging, interactive, and technology‑driven learning experience. Equipped with advanced digital teaching tools, interactive displays, projectors, and multimedia resources, these classrooms make lessons more dynamic,visual, and easy to understand.By integrating technology with the curriculum, teachers create immersive learning experiences that encourage active participation, critical thinking, and collaborative learning. Audio‑visual presentations, educational videos, animations, and digital content help simplify complex concepts, making learning more enjoyable and effective for students.Our Smart Classrooms foster creativity, curiosity, and innovation while preparingstudents with the digital skills required for the 21st century. They provide an inclusive and stimulating environment where every learner is inspired to achieve </span></p><p><span class=\\\"ql-font-playfair\\\">academic excellence and develop a lifelong love for learning.At Malviya Convent School, our Smart Classrooms are designed to transform traditional teaching into an engaging, interactive, and technology‑driven learning experience. Equipped with advanced digital teaching tools, interactive displays, projectors, and multimedia resources, these classrooms make lessons more dynamic,visual, and easy to understand.By integrating technology with the curriculum, teachers create immersive learning experiences that encourage active particip