INSERT INTO `tbl_module_content` (`id`, `school_id`, `module_key`, `content`, `is_published`, `created_at`, `updated_at`) VALUES (384, 9, 'sports', '{\"sportsAt\":{\"heading\":\"Sports at MCS\",\"description\":\"<p><span class=\\\"ql-font-merriweather\\\">At Malviya Convent School, we believe that sports play a vital role in the holistic development of every student. Our comprehensive sports program encourages physical fitness, teamwork, discipline, leadership, and sportsmanship while promoting a healthy and active lifestyle.The school provides students with opportunities to participate in a wide range of indoor and outdoor sports, including cricket, football, basketball, volleyball,badminton, table tennis, athletics, yoga, and other recreational activities. Regular coaching sessions, inter‑house competitions, and annual sports events help students develop their skills, confidence, and competitive spirit.Our experienced physical education instructors guide students to excel both on and off the field by emphasizing perseverance, fair play, and respect for others. Through sports, we strive to nurture well‑rounded individuals who are physically fit, mentally resilient, and prepared to face life&#39;s challenges with determination and confidence.</span></p>\",\"images\":[\"https://res.cloudinary.com/dllspz9pv/image/upload/v1786806998/school-saas/content/iwrbw6skzvf47e0fryfs.jpg\",\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783953748/school-saas/content/ywb4lsgpjqnw4fwv2geb.jpg\",\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783953920/school-saas/content/hfzk4rsgcopcb76qhoxp.jpg\",\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783953985/school-saas/content/ahep12czn2gxtcpsjquf.jpg\",\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783953846/school-saas/content/smuohxdse3v0crlq0hze.jpg\",\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783953805/school-saas/content/qjg2vkkrpxbfou97w5xe.jpg\",\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783953871/school-saas/content/qbm4pvijdy7t589wt3gx.jpg\"],\"collageLayout\":\"5\",\"showHeading\":true,\"banner\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783502889/school-saas/content/k3j7umj47oicptbc4hwx.jpg\",\"headingItalic\":false,\"headingFont\":\"playfair\",\"collageImages\":{\"4\":[],\"5\":[\"https://res.cloudinary.com/dllspz9pv/image/upload/v1786806998/school-saas/content/iwrbw6skzvf47e0fryfs.jpg\",\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783953748/school-saas/content/ywb4lsgpjqnw4fwv2geb.jpg\",\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783953920/school-saas/content/hfzk4rsgcopcb76qhoxp.jpg\",\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783953985/school-saas/content/ahep12czn2gxtcpsjquf.jpg\",\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783953846/school-saas/content/smuohxdse3v0crlq0hze.jpg\",\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783953805/school-saas/content/qjg2vkkrpxbfou97w5xe.jpg\",\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783953871/school-saas/content/qbm4pvijdy7t589wt3gx.jpg\"],\"7\":[]}},\"sportsOffered\":{\"heading\":\"Sports Offered at Malviya Convent School\",\"description\":\"<p class=\\\"ql-align-justify\\\"><span class=\\\"ql-font-playfair\\\">At Malviya Convent School, students are encouraged to participate in a wide range of sports and fitness activities that promote physical well‑being,teamwork, discipline, and leadership. The school believes that sports are an integral part of holistic education and provides opportunities for students to develop their athletic abilities through regular practice and competitions.</span></p>\",\"offeredSports\":[{\"id\":\"sport‑1783503217052\",\"heading\":\"Football\",\"description\":\"<p class=\\\"ql-align-justify\\\"><span class=\\\"ql-font-playfair\\\">Football is one of the most popular team sports at Malviya Convent School. It helps students develop teamwork, coordination, endurance, and strategic thinkin while promoting physical fitness and sportsmanship.Football is one of the most popular team sports at Malviya Convent School. It helps students develop teamwork, coordination, endurance, and strategic thinkin while promoting physical fitness and sportsmanship.Football is one of the most popular team sports at Malviya Convent School. It helps students develop teamwork, coordination, endurance, and strategic thinkin while promoting physical fitness and sportsmanship.Football is one of the most popular team sports at Malviya Convent School. It helps students develop teamwork, coordination, endurance, and strategic thinkin while promoting physical fitness and sportsmanship.Football is one of the most popular team sports at Malviya Convent School. It helps students develop teamwork, coordination, endurance, and strategic thinkin while promoting physic endurance, and strategic thinkin while promoting physical fitness and sportsmanship.Football is </span></p>\",\"images\":[\"https://res.cloudinary.com/dllspz9pv/image/upload/v1784979217/school-saas/content/aqxggqg9qktqfm8t0ld4.jpg\",\"https://res.cloudinary.com/dllspz9pv/image/upload/v1784979240/school-saas/content/j2dqymvugtqwqasj8tjv.jpg\",\"https://res.cloudinary.com/dllspz9pv/image/upload/v1784979253/school-saas/content/kilztlp8eubvyxv6navr.jpg\"]},{\"id\":\"sport‑1783503382456\",\"heading\":\"Cricket\",\"description\":\"<p class=\\\"ql-align-justify\\\">Cricket encourages discipline, concentration, leadership, and teamwork. Students learn essential skills such as batting, bowling, and fielding while building confidence and a competitive spirit through regular practice and matches.Cricket encourages discipline, concentration, leadership, and teamwork. Students learn essential skills such as batting, bowling, and fielding while building confidence and a competitive spirit through regular practice and matches.Cricket encourages discipline, concentration, leadership, and teamwork. Students learn essential skills such as batting, bowling, and fielding while building confidence and a competitive spirit through regular practice and matches.Cricket encourages discipline, concentration, leadership, and teamwork. Students learn essential skills such as batting, bowling, and fielding while building confidence and a competitive spirit through regular practice and matches.Cricket encourages discipline, concentration, leadership, and teamwork. Students learn essential skills such as batting, bowling, and fielding while building confidence and a competitive spirit through regular practice and matches.Cricket encourages discipline, concentration, leadership, and teamwork. Students learn essential skills such as batting, bowling, and fielding while building confidence and a competitive spirit through regular practice and matches.Cricket encourages discipline, concentration, leadership, and teamwork. Students learn essential skills such as batting, bowling, and fielding while building confidence and a competitive spirit through regular practice and matches.Cricket encourages discipline, concentration, leadership, and teamwork. Students learn essential skills such as batting, bowling, and fielding while building confidence and a competitive</p>\",\"images\":[\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783954492/school-saas/content/i6fvdkfhaf8i7ubvge2g.jpg\",\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783954513/school-saas/content/egtsmqydesbzvr3ckenp.jpg\"]},{\"id\":\"sport‑1783503571231\",\"heading\":\"Basketball\",\"description\":\"<p class=\\\"ql-align-justify\\\">Basketball promotes teamwork, speed, coordination, and physical endurance. Through regular training and friendly competitions, students develop leadership qualities, communication skills, and the ability to perform effectively under pressure. Basketball promotes teamwork, speed, coordination, and physical endurance. Through regular training and friendly competitions, students develop leadership</p><p class=\\\"ql-align-justify\\\">qualities, communication skills, and the ability to perform effectively under pressure. Basketball promotes teamwork, speed, coordination, and physical endurance.  spirit through regular practice and matches.Cricket encourages discipline, concentration, leadership, and teamwork. Students learn essential skills such as batting, bowling, and fielding while building confidence and a competitive spirit through regular practice and matches.Cricket encourages discipline, concentration, leadership, and teamwork. Students learn essential skills such as batting, bowling, and fielding while building confidence and a competitive spirit through regular practice and matches.Cricket encourages discipline, concentration, leadership, and teamwork. </p>\",\"images\":[\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783954547/school-saas/content/nod9ezojyvjtdlbqdjru.jpg\",\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783954574/school-saas/content/kwefv8m8qrnxacu8jy25.jpg\"]}],\"showHeading\":true,\"banner\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783503136/school-saas/content/lmvrom1wh6xbj4tgtbrz.jpg\",\"headingItalic\":false,\"headingFont\":\"playfair\"},\"sportingEvents\":{\"heading\":\"Sporting Events at Malviya Convent School\",\"description\":\"<p>The Annual Sports Day is one of the most anticipated events of the academic year,bringing together students, teachers, and parents in a celebration of athletic excellenceand teamwork. The event features a ceremonial march‑past, track and field competitions, team games, and prize distribution, encouraging students to showcase their talents while embracing the values of discipline, determination, and sportsmanship.The Annual Sports Day is one of the most anticipated events of the academic year,bringing together students, teachers, and parents in a celebration of athletic excellenceand teamwork. The event features a ceremonial march‑past, track and field competitions, team games, and prize distribution, encouraging students to showcase their talents while embracing the values of discipline, determination, and sportsmanship.The Annual Sports Day is one of the most anticipated events of the academic year,bringing together students, teachers, and parents in a celebration of athletic excellenceand teamwork.</p>\",\"events\":[{\"id\":\"ev‑1783503782173\",\"heading\":\"Mini Olympic Sports Day\",\"description\":\"<p>Designed especially for our young learners, the Mini Olympic Sports Day introduces students to the joy of sports through fun races, skill‑based activities, and engaging fitness events. The event promotes physical development, confidence, coordination, and healthy competition in an exciting and encouraging environment.Designed especially for our young learners, the Mini Olympic Sports Day introduces students to the joy of sports through fun races, skill‑based activities, and engaging fitness events. The event promotes physical development, confidence, coordination, and healthy competition in an exciting and encouraging environment.Designed especially for our young learners, the Mini Olympic Sports Day introduces students to the joy of sports through fun races, skill‑based activities, and engaging fitness events. The event promotes physical development, confidence, coordination, and healthy competition in an exciting and encouraging environment.Designed especially for our young learners, the Mini Olympic Sports Day introduces students to the joy of sports through fun races, skill‑based activities, and engaging fitness events.</p>\",\"images\":[\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783954818/school-saas/content/xgaprufy5pofpn1hb3d2.jpg\",\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783954837/school-saas/content/ruazwpjqakx5fxiuj6d2.jpg\"]}],\"showHeading\":true,\"banner\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783503703/school-saas/content/hdfsudxblyh3wsxl4ij0.jpg\",\"headingFont\":\"playfair\"},\"clubsActivities\":{\"heading\":\"MCS Clubs\",\"description\":\"<p>At Malviya Convent School, sports are an integral part of student life. Our diverse range of sports clubs and events encourages students to stay active, build teamwork and leadership skills, and develop a spirit of healthy competition. From football and cricket to badminton, athletics, yoga, and martial arts, students get opportunities to discover their talents, participate in competitions, and celebrate their achievements on and off the field.</p>\",\"clubs\":[{\"id\":\"club‑1788259458933\",\"heading\":\"Football Club\",\"description\":\"<p>Training, inter‑house matches and competitive tournaments.Training, inter‑house matches and competitive tournaments.Training, inter‑house matches and competitive tournaments.Training, inter‑house matches and competitive tournaments.Training, inter‑house matches and competitive tournaments.Training, inter‑house matches and competitive tournaments.Training, inter‑house matches and competitive tournaments.Training, inter‑house matches and competitive tournaments.</p>\",\"images\":[\"https://res.cloudinary.com/dllspz9pv/image/upload/v1788259527/school-saas/content/school-9/osy2yn0s8sv327o4lq8p.jpg\",\"https://res.cloudinary.com/dllspz9pv/image/upload/v1788259531/school-saas/content/school-9/qmzyx0slo9axurpa7nrx.jpg\",\"https://res.cloudinary.com/dllspz9pv/image/upload/v1788259533/school-saas/content/school-9/fwagdmvvqblo3yjyzyip.jpg\",\"https://res.cloudinary.com/dllspz9pv/image/upload/v1788259538/school-saas/content/school-9/ea1rusofdcfpry6uzsgd.jpg\",\"https://res.cloudinary.com/dllspz9pv/image/upload/v1788259542/school-saas/content/school-9/aubhrbs5c7siev8gc4po.jpg\"]}]},\"awards\":{\"heading\":\"Sports Awards and Achievements\",\"description\":\"<p class=\\\"ql-align-justify\\\">मालवीय At Malviya Convent School, we take immense pride in the sporting accomplishments of our students. Through regular training, dedicated coaching, and participation in various competitions, our young athletes continue to demonstrate excellence, determination, and outstanding sportsmanship.</p><p class=\\\"ql-align-justify\\\"></p><p class=\\\"ql-align-justify\\\">Our students have earned recognition in a wide range of sporting events, bringing laurels to the school at inter‑school, district, and state‑level competitions. From football and cricket to basketball and badminton, MCS encourages every student to pursue their passion for sports while developing discipline, teamwork, and leadership.</p><p class=\\\"ql-align-justify\\\"></p><p class=\\\"ql-align-justify\\\">Every achievement reflects the hard work of our students, the guidance of our coaches, and the unwavering support of the school community. We remain committed to nurturing future champions by providing opportunities that inspire confidence, resilience, and a lifelong love for sports.</p>\",\"images\":[\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783955014/school-saas/content/qtdsa8niusskbrziyrly.jpg\",\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783955026/school-saas/content/yghydsowtj02vmuzgoam.jpg\",\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783955030/school-saas/content/ahlensow4suienlcleew.jpg\"],\"certifications\":[{\"id\":\"cert‑1783506827203\",\"image\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783955112/school-saas/content/wagag4o4da59yyteul8p.jpg\",\"title\":\"football \",\"info\":\"Our football certificate winners have demonstrated\"},{\"id\":\"cert‑1783665449209\",\"image\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783665457/school-saas/content/p2hqr6ckwgpsyh4rwavz.webp\",\"title\":\"Rahul Parmar\",\"info\":\"Our football certificate winners have demonstrated\"},{\"id\":\"cert‑1783665466389\",\"image\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783955146/school-saas/content/o8xqcpskovbqampvucxx.jpg\",\"title\":\"Samarth Shandilya\",\"info\":\"Our chess certificate winners have displayed outstanding strategies\"}],\"proud\":[{\"id\":\"proud‑1783507097505\",\"photo\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783665530/school-saas/content/nj02qeiayc2pu7ujxkme.jpg\",\"name\":\"Sunny Kapoor\",\"achievement\":\"Our chess certificate winners have displayed outstanding strategic thinking, patience, and analytical skills in competitive tournaments. Their success is a testament to their concentration, determination, and intellectual ability. Malviya Convent School applauds their achievements and encourages all students to develop confidence and excellence through both academic and co‑curricular pursuits.\"},{\"id\":\"proud‑1783665637117\",\"photo\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783665676/school-saas/content/dbe1kbiviaiku1ranl7h.jpg\",\"name\":\"Simon Sinner\",\"achievement\":\"Our chess certificate winners have displayed outstanding strategic thinking, patience, and analytical skills in competitive tournaments. Their success is a testament to their concentration, determination, and intellectual ability. Malviya Convent School applauds their achievements and encourages all students to develop confidence and excellence through both academic and co‑curricular pursuits.\"},{\"id\":\"proud‑1783665686679\",\"photo\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783665700/school-saas/content/b52xzhbqppg4casenyxj.jpg\",\"name\":\"Shreyansh \",\"achievement\":\"Our chess certificate winners have displayed outstanding strategic thinking, patience, and analytical skills in competitive tournaments. Their success is a testament to their concentration, determination, and intellectual ability. Malviya Convent School applauds their achievements and encourages all students to develop confidence and excellence through both academic and co‑curricular pursuits.\"}],\"yearlyAwards\":[{\"id\":\"yr‑1783507117415\",\"year\":\"2022‑23\",\"pdfUrl\":\"https://res.cloudinary.com/dllspz9pv/raw/upload/v1783507129/school-saas/documents/ywlnhklrm400xczi0led\"},{\"id\":\"yr‑1783665578853\",\"year\":\"2023‑24\",\"pdfUrl\":\"https://res.cloudinary.com/dllspz9pv/raw/upload/v1783665596/school-saas/documents/bl27uyatj47f8xkyowxs\"},{\"id\":\"yr‑1783665599026\",\"year\":\"2024‑25\",\"pdfUrl\":\"https://res.cloudinary.com/dllspz9pv/raw/upload/v1783665611/school-saas/documents/ezzjrcxbyrv0lhyptnic\"},{\"id\":\"yr‑1783665612182\",\"year\":\"2025‑26\",\"pdfUrl\":\"https://res.cloudinary.com/dllspz9pv/raw/upload/v1783665624/school-saas/documents/bmqvmyz5pkvyubpiwfyo\"}],\"showHeading\":true,\"banner\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783506782/school-saas/content/lvhkasaazawg8e8kcseb.jpg\",\"headingFont\":\"playfair\",\"headingColor\":\"\"}}', 1, '2026-07-08 03:59:00', '2026-09-01 05:15:47');
INSERT INTO `tbl_module_content` (`id`, `school_id`, `module_key`, `content`, `is_published`, `created_at`, `updated_at`) VALUES (398, 9, 'courses', '{\"preprimary\":{\"enabled\":true,\"aboutHeading\":\"Pre Primary School\",\"aboutQuote\":\"<p><span style=\\\"color: rgb(15, 23, 42); background-color: rgb(255, 255, 255);\\\">Pre Primary SchoolPre Primary SchoolPre Primary SchoolPre Primary School</span></p>\",\"aboutAuthor\":\"\",\"aboutAuthorDesignation\":\"\",\"aboutImage\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1788785408/school-saas/content/school-9/tvnkl7ltytrkh56qgff4.jpg\",\"uniqueHeading\":\"\",\"uniqueText\":\"\",\"uniqueImage\":\"\",\"gallery\":[]},\"primary\":{\"enabled\":true,\"aboutHeading\":\"About Primary School\",\"aboutQuote\":\"<p><span style=\\\"color: rgb(15, 23, 42); background-color: rgb(255, 255, 255);\\\">Pre Primary SchoolPre Primary SchoolPre Primary SchoolPre Primary School</span></p>\",\"aboutAuthor\":\"Jessica Waugh\",\"aboutAuthorDesignation\":\"Head of Primary School\",\"aboutImage\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1784978611/school-saas/content/ttyvwnudejenjwnxrx5d.jpg\",\"uniqueHeading\":\"Why Primary School is Unique\",\"uniqueText\":\"<p><span class=\\\"ql-font-playfair\\\">What makes the Primary School at Malviya Convent School truly unique is our child‑centric approach to education. We recognize that every child learns differently, and therefore we provide personalized attention, continuous encouragement, and a supportive atmosphere that helps every student thrive. Our classrooms are vibrant spaces where learning is made enjoyable through hands‑on activities, storytelling, digital learning tools, and collaborative experiences.</span></p><p><span class=\\\"ql-font-playfair\\\">Equipped with smart classrooms and guided by dedicated educators, we create meaningful learning experiences that extend beyond textbooks. Equal emphasis is placed on academics, character building, creativity, communication, leadership, and physical well‑being. By fostering confidence, curiosity, discipline, and strong moral values from an early age, we ensure that our students not only excel academically but also grow into responsible, compassionate, and future‑ready individuals.</span></p>\",\"uniqueImage\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1784978649/school-saas/content/mukggiolvkrujohqichf.jpg\",\"gallery\":[\"https://res.cloudinary.com/dllspz9pv/image/upload/v1784980253/school-saas/content/qfc7x1un2sznggidelfx.jpg\",\"https://res.cloudinary.com/dllspz9pv/image/upload/v1784980256/school-saas/content/hudvof9fnj05bsdbuwha.jpg\",\"https://res.cloudinary.com/dllspz9pv/image/upload/v1784980259/school-saas/content/x3h0md3dtrqi69wjvx4q.jpg\",\"https://res.cloudinary.com/dllspz9pv/image/upload/v1784980269/school-saas/content/pnqy8rncqfqahyx71zi8.jpg\"],\"contacts\":[{\"photo\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783664749/school-saas/content/fyxkpkpjfzvzwauob0jj.jpg\",\"name\":\"Jude Walt\",\"designation\":\"Faculty\",\"email\":\"jude@walt.com\",\"phone\":\"9885528889\"},{\"photo\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783664787/school-saas/content/ot6984via0cbs2ujko8x.jpg\",\"name\":\"Marty Mauser\",\"designation\":\"Faculty\",\"email\":\"martin@supreme.com\",\"phone\":\"4555698712\"}],\"bannerImage\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783505443/school-saas/content/klnetll78fv4assqyaud.jpg\",\"aboutHeadingColor\":\"#000000\"},\"middle\":{\"enabled\":true,\"aboutHeading\":\"About Middle School\",\"aboutQuote\":\"<p><span style=\\\"color: rgb(15, 23, 42); background-color: rgb(255, 255, 255);\\\">Pre Primary SchoolPre Primary SchoolPre Primary SchoolPre Primary School</span></p>\",\"aboutAuthor\":\"Muskan Sanon\",\"aboutAuthorDesignation\":\"Head of Middle School\",\"aboutImage\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783937383/school-saas/content/uhi3rs8ppoogteiwsvud.jpg\",\"uniqueHeading\":\"Why Middle School Is Unique\",\"uniqueText\":\"<p>At Malviya Convent School, our Middle School stands out for its learner‑centered approach that nurtures curiosity, independence, and leadership. We integrate innovative teaching methods, smart classrooms, practical learning experiences, and personalized guidance to make education engaging and meaningful. Along with academic excellence, we place equal emphasis on character building, teamwork, communication, and holistic development, ensuring that every student is equipped with the confidence, knowledge, and skills needed to excel in higher education and beyond.</p>\",\"uniqueImage\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783937536/school-saas/content/nmiqx6dt7jhm5lsjdlvh.jpg\",\"gallery\":[\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783937585/school-saas/content/w6sdtxozsxxckaaci1u1.jpg\",\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783937607/school-saas/content/nnytygqdnuxxb2prf1f7.jpg\"],\"contacts\":[],\"bannerImage\":\"\"},\"high\":{\"enabled\":true,\"aboutHeading\":\"About High School\",\"aboutQuote\":\"<p><span style=\\\"color: rgb(15, 23, 42); background-color: rgb(255, 255, 255);\\\">Pre Primary SchoolPre Primary SchoolPre Primary SchoolPre Primary School</span></p>\",\"aboutAuthor\":\"Shahid Kapoor\",\"aboutAuthorDesignation\":\"Head of High School\",\"aboutImage\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783938088/school-saas/content/uc8bbk6bjkyfegtgph0o.jpg\",\"uniqueHeading\":\"Why High School is Unique\",\"uniqueText\":\"<p>The High School at Malviya Convent School stands apart because of its learner‑focused approach that combines academic excellence with holistic development. Our innovative teaching methodologies, smart classrooms, well‑equipped laboratories, and technology‑enabled learning environment ensure that students gain a deeper understanding of concepts while developing practical knowledge and critical thinking abilities.</p><p>Beyond academics, we encourage students to discover and nurture their talents through sports, performing arts, leadership opportunities, social service activities, and inter‑school competitions. Individual attention, continuous assessment, and regular mentoring enable every student to overcome challenges and achieve success according to their unique strengths. Our emphasis on discipline, values, confidence, resilience, and lifelong learning prepares students not only for board examinations but also for the demands of higher education and an ever‑changing world.</p>\",\"uniqueImage\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783938185/school-saas/content/f7iecixbo3con856em7h.jpg\",\"gallery\":[\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783938370/school-saas/content/mlwq9vrtqyl6j0b250ug.jpg\",\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783938608/school-saas/content/qdzl2lxeb1n4n5ktysmo.jpg\"],\"contacts\":[],\"bannerImage\":\"\"},\"senior\":{\"enabled\":true,\"aboutHeading\":\"\",\"aboutQuote\":\"<p><span style=\\\"color: rgb(15, 23, 42); background-color: rgb(255, 255, 255);\\\">Pre Primary SchoolPre Primary SchoolPre Primary SchoolPre Primary School</span></p>\",\"aboutAuthor\":\"\",\"aboutAuthorDesignation\":\"\",\"aboutImage\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783937360/school-saas/content/uvrprtmqch9e1cwhunsm.jpg\",\"uniqueHeading\":\"\",\"uniqueText\":\"\",\"uniqueImage\":\"\",\"gallery\":[],\"contacts\":[],\"bannerImage\":\"\"}}', 1, '2026-07-08 04:44:06', '2026-09-07 07:30:48');
INSERT INTO `tbl_module_content` (`id`, `school_id`, `module_key`, `content`, `is_published`, `created_at`, `updated_at`) VALUES (413, 9, 'gallery', '{\"photoNodes\":[{\"id\":\"f‑1787759753493\",\"parentId\":null,\"type\":\"folder\",\"name\":\"Indepen Day\",\"images\":[\"https://res.cloudinary.com/dllspz9pv/image/upload/v1787759782/school-saas/content/school-9/knmtfqsdntymxjdlaatw.jpg\"],\"videos\":[],\"coverImage\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1788260177/school-saas/content/school-9/yaidq2ad1cpeckd2dzbr.jpg\",\"priority\":3,\"createdAt\":\"2026‑08‑26T15:55:53.493Z\"},{\"id\":\"f‑1788260341339\",\"parentId\":null,\"type\":\"folder\",\"name\":\"Campus\",\"images\":[\"https://res.cloudinary.com/dllspz9pv/image/upload/v1788260400/school-saas/content/school-9/w3k6gwtsalssg1wzztvq.jpg\",\"https://res.cloudinary.com/dllspz9pv/image/upload/v1788260407/school-saas/content/school-9/s4yjdwj1ucz3mh6rt3xe.jpg\",\"https://res.cloudinary.com/dllspz9pv/image/upload/v1788260413/school-saas/content/school-9/zqza8ulbc3lpszthcduw.jpg\",\"https://res.cloudinary.com/dllspz9pv/image/upload/v1788260420/school-saas/content/school-9/kmn5191vqtrskspxgn6r.jpg\",\"https://res.cloudinary.com/dllspz9pv/image/upload/v1788260426/school-saas/content/school-9/ooam60quhokzqbmbr0vk.jpg\"],\"videos\":[],\"coverImage\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1788260367/school-saas/content/school-9/zs3ibmcovhz80tap026j.jpg\",\"priority\":2,\"createdAt\":\"2026‑09‑01T10:59:01.339Z\"}],\"videoNodes\":[{\"id\":\"f‑1788261424813\",\"parentId\":null,\"type\":\"folder\",\"name\":\"Gallery Testing\",\"images\":[],\"videos\":[{\"id\":\"vid‑1788261441576\",\"title\":\"Test_1\",\"date\":\"2026‑09‑01\",\"sourceType\":\"youtube\",\"youtubeUrl\":\"https://youtu.be/XvFmUE-36Kc\",\"videoUrl\":\"\",\"thumbnail\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1788261539/school-saas/content/school-9/cmoz82zncs6t6fly4aoz.jpg\"},{\"id\":\"vid‑1788261524399\",\"title\":\"Test_2\",\"date\":\"\",\"sourceType\":\"youtube\",\"youtubeUrl\":\"https://youtu.be/XvFmUE-36Kc\",\"videoUrl\":\"\",\"thumbnail\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1788261544/school-saas/content/school-9/eybsxfjk1wvzm0wlu1yi.jpg\"}],\"coverImage\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1788261437/school-saas/content/school-9/tbw6m3yb3efydhyjnjtv.jpg\",\"priority\":1,\"createdAt\":\"2026‑09‑01T11:17:04.813Z\"}],\"photoBanner\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783625348/school-saas/content/itn42pvfkgdnviobgwqn.jpg\",\"videoBanner\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783511819/school-saas/content/fmvkhdwzgddx7fw043kb.jpg\"}', 1, '2026-07-08 06:26:25', '2026-09-01 05:49:08');
INSERT INTO `tbl_module_content` (`id`, `school_id`, `module_key`, `content`, `is_published`, `created_at`, `updated_at`) VALUES (419, 9, 'tc', '{\"heading\":\"Download Transfer Certificate\",\"headingItalic\":false,\"headingColor\":\"\",\"headingFont\":\"\",\"description\":\"<p>You Can Download your TC from here by filling in session TC number or student name</p>\",\"sessions\":[{\"id\":\"sess‑mrj4v3iv‑bgss5\",\"name\":\"2022‑23\",\"records\":[{\"id\":\"tc‑mrj4z6q1‑vgi1r\",\"tcNo\":\"TC001\",\"studentName\":\"Pulkit Mathur\",\"pdfUrl\":\"https://res.cloudinary.com/dllspz9pv/raw/upload/v1783941945/school-saas/documents/zwxoooackr1pnwzeadtb\"},{\"id\":\"tc‑mrj4zt0r‑0cgio\",\"tcNo\":\"TC002\",\"studentName\":\"Rahul Parmar\",\"pdfUrl\":\"https://res.cloudinary.com/dllspz9pv/raw/upload/v1783941977/school-saas/documents/ujhaemhfs60ciwmq90tz\"},{\"id\":\"tc‑mrj50f2z‑3juyh\",\"tcNo\":\"TC003\",\"studentName\":\"Aman Soni\",\"pdfUrl\":\"https://res.cloudinary.com/dllspz9pv/raw/upload/v1783942007/school-saas/documents/yuizgjfc7qbx5wn0x1n5\"},{\"id\":\"tc‑mrjoxf60‑s0098\",\"tcNo\":\"TC004\",\"studentName\":\"Pulkit Mathur\",\"pdfUrl\":\"https://res.cloudinary.com/dllspz9pv/raw/upload/v1783975459/school-saas/documents/cpennbfuepskdorpndsn\"},{\"id\":\"tc‑mtiiusz4‑mleuk\",\"tcNo\":\"TC007\",\"studentName\":\"Ishita Bhatia\",\"pdfUrl\":\"https://res.cloudinary.com/dllspz9pv/raw/upload/v1788258357/school-saas/documents/school-9/1788258354238-ISE_assignment_2__2_.pdf\"},{\"id\":\"tc‑mtzrl1d4‑8twij\",\"tcNo\":\"TC011\",\"studentName\":\"Manyata Sharma\",\"pdfUrl\":\"https://res.cloudinary.com/dllspz9pv/raw/upload/v1789300942/school-saas/documents/school-9/1789300942432-tempPdf.pdf\"}]},{\"id\":\"sess‑mrj53m6n‑n56u5\",\"name\":\"2023‑24\",\"records\":[{\"id\":\"tc‑mrj54ecz‑bxz9s\",\"tcNo\":\"TC007\",\"studentName\":\"Riya Sharma\",\"pdfUrl\":\"https://res.cloudinary.com/dllspz9pv/raw/upload/v1783942192/school-saas/documents/pbijgi3wq6c9rnnpbrwd\"}]}]}', 1, '2026-07-08 06:37:32', '2