INSERT INTO `tbl_module_content` (`id`, `school_id`, `module_key`, `content`, `is_published`, `created_at`, `updated_at`) VALUES (421, 9, 'disclosure', '{\"heading\":\"Mandatory Public Disclosure\",\"description\":\"<p></p>\",\"disclosurePdf\":{\"label\":\"Mandatory Public Disclosure\",\"pdfUrl\":\"https://res.cloudinary.com/dllspz9pv/raw/upload/v1783677108/school-saas/documents/mp6mxokxqjfi3vpkjtrh\"},\"categories\":[{\"type\":\"info\",\"id\":\"cat‑a\",\"name\":\"General Information\",\"rows\":[{\"id\":\"a1\",\"label\":\"Name of the School\",\"details\":\"MALVIYA CONVENT SCHOOL\"},{\"id\":\"a2\",\"label\":\"Affiliation No. (if applicable)\",\"details\":\"\\t1730506\"},{\"id\":\"a3\",\"label\":\"School Code\",\"details\":\"\\t10852\"},{\"id\":\"a4\",\"label\":\"Complete Address with Pin Code\",\"details\":\"2‑Institutional Area, A Block, Sudha Sagar Colony, Near Kardhani Shopping Centre, Malviya Nagar, Jaipur, Rajasthan 302017\"},{\"id\":\"a5\",\"label\":\"Principal Name \",\"details\":\"Mrs. Svetika Kapoor\"},{\"id\":\"a6\",\"label\":\"School Email ID\",\"details\":\"Malviya.mcs2019@gmail.com\"},{\"id\":\"a7\",\"label\":\"Contact Details (Landline/Mobile)\",\"details\":\"0141‑2522447 / 8852991000\"}]},{\"type\":\"documents\",\"id\":\"cat‑b\",\"name\":\"Documents and Information\",\"rows\":[{\"id\":\"b3\",\"label\":\"Copy of No Objection Certificate (NOC) Issued, if applicable, by the State Govt./UT\",\"pdfUrl\":\"\",\"linkUrl\":\"https://drive.google.com/file/d/1VVHC4xayX-FOmwhvcmtrnOHolOepGGt1/view\"},{\"id\":\"b4\",\"label\":\"Copies of Recognition Certificate under RTE Act, 2009, and it\'s renewal if applicable\",\"pdfUrl\":\"\",\"linkUrl\":\"https://drive.google.com/file/d/1hKbP3LuUQB885m1W6EsNf1QLvksiQgrk/view\"},{\"id\":\"b5\",\"label\":\"Copy of Valid Building Safety Certificate\",\"pdfUrl\":\"\",\"linkUrl\":\"https://drive.google.com/file/d/1Gc--Logc5UKfRmJS5aF-xyis4bFaHt_1/view\"},{\"id\":\"b6\",\"label\":\"Copy of Valid Fire Safety Certificate\",\"pdfUrl\":\"\",\"linkUrl\":\"https://drive.google.com/file/d/1vSDI8Os9tu37hk2KxJFG8fuulzqakR0T/view\"},{\"id\":\"row‑1783514472803\",\"label\":\"COPY OF THE DEO CERTIFICATE SUBMITTED BY THE SCHOOL FOR AFFILIATION/UPGRADATION/EXTENSION OF AFFILIATIONOR SELF CERTIFICATION BY SCHOOL\",\"pdfUrl\":\"\",\"linkUrl\":\"https://drive.google.com/file/d/19dIKQbM5TCjEcO5NhfZnYIbTuzMpsLPV/view\",\"description\":\"\"},{\"id\":\"row‑1783514485874\",\"label\":\"COPIES OF VALID DRINKING WATER, HEALTH AND SANITATION CERTIFICATES AND WATER TESTING REPORT\",\"pdfUrl\":\"https://res.cloudinary.com/dllspz9pv/raw/upload/v1786455214/school-saas/documents/1786455207697-School_Affiliation.pdf\",\"linkUrl\":\"\",\"description\":\"\"}]},{\"type\":\"info\",\"id\":\"cat‑d\",\"name\":\"Staff Details (Teaching)\",\"rows\":[{\"id\":\"d1\",\"label\":\"Principal\",\"details\":\"1\"},{\"id\":\"d2\",\"label\":\"No. of Teachers (PGT / TGT / PRT)\",\"details\":\"42\"},{\"id\":\"d3\",\"label\":\"Teacher Section Ratio\",\"details\":\"\"},{\"id\":\"d4\",\"label\":\"Details of Special Educator\",\"details\":\"\"},{\"id\":\"d5\",\"label\":\"Details of Counsellor and Wellness Teacher\",\"details\":\"\"}]},{\"type\":\"info\",\"id\":\"cat‑e\",\"name\":\"School Infrastructure\",\"rows\":[{\"id\":\"e1\",\"label\":\"Total Campus Area of School in Square Metre\",\"details\":\"\"},{\"id\":\"e2\",\"label\":\"No. and Size of Classroom in Square Metre\",\"details\":\"\"},{\"id\":\"e3\",\"label\":\"No. and Size of Laboratories including Computer Labs in Square Metre\",\"details\":\"\"},{\"id\":\"e4\",\"label\":\"Internet Facility (Y/N)\",\"details\":\"\"},{\"id\":\"e5\",\"label\":\"No. of Girls Toilets\",\"details\":\"\"},{\"id\":\"e6\",\"label\":\"No. of Boys Toilets\",\"details\":\"\"}]}],\"banner\":\"\",\"headingItalic\":false}', 1, '2026-07-08 07:11:48', '2026-08-30 00:51:02');
INSERT INTO `tbl_module_content` (`id`, `school_id`, `module_key`, `content`, `is_published`, `created_at`, `updated_at`) VALUES (423, 9, 'alumni', '{\"heading\":\"Malviya Convents Alumini\",\"description\":\"<p class=\\\"ql-align-justify\\\"><span class=\\\"ql-font-merriweather\\\">At Malviya Convent School, our alumni are a true reflection of the values, knowledge, and excellence nurtured within our classrooms. They have gone on to pursue successful careers in diverse fields, including engineering, medicine, business, education, technology, public service, and entrepreneurship, making meaningful contributions to society. The achievements of our former students inspire current learners to dream big, work hard, and strive for excellence. Their continued connection with the school strengthens the MCS community and reinforces our commitment to shaping confident, responsible, and compassionate individuals. We take immense pride in our alumni and celebrate their accomplishments as they continue to uphold the legacy and values of Malviya Convent School wherever they go.</span></p>\",\"alumni\":[{\"id\":\"alum‑1783515083338\",\"photo\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1789467385/school-saas/content/school-9/dyref8jdjfl56e9lzto1.jpg\",\"name\":\"Aanya Mehta\",\"batchYear\":\"2019\",\"achievementHeadline\":\"Currently in IIT Guhati \",\"testimonial\":\"<p><span class=\\\"ql-font-playfair\\\">Malviya Convent School takes immense pride in the achievements of its alumna, Aanya Mehta, a distinguished member of the 2019 batch, who earned admission to the prestigious Indian Institute of Technology (IIT) Guwahati. Her journey reflects the values of dedication, perseverance, and academic excellence instilled during her years at MCS. Aanya&#39;s accomplishment serves as an inspiration to aspiring students, demonstrating that hard work, determination, and the right guidance can lead to remarkable success. The entire MCS family celebrates her achievement and wishes her continued excellence in all her future endeavors.</span></p>\",\"linkedinUrl\":\"\"}],\"banner\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783515071/school-saas/content/hadv0st1bwv1u3j2tvv8.jpg\",\"headingItalic\":false}', 1, '2026-07-08 07:23:43', '2026-09-15 04:46:29');
INSERT INTO `tbl_module_content` (`id`, `school_id`, `module_key`, `content`, `is_published`, `created_at`, `updated_at`) VALUES (427, 9, 'achievements', '{\"heading\":\"Our Achievements\",\"description\":\"<p><span class=\\\"ql-font-playfair\\\">Malviya Convent School takes pride in its consistent pursuit of excellence across academics, sports, and co‑curricular activities. Our students have consistently delivered outstanding performances in the CBSE Board Examinations, with many securing distinctions, subject toppers, and scores above 90%, reflecting the school&#39;s strong academic foundation. They actively participate in national and inter‑school Olympiads, quizzes, and academic competitions, earning top positions and bringing laurels to the school through their exceptional performance. Beyond the classroom, MCS students have excelled in various sporting events including Taekwondo, athletics, football, cricket, basketball, and badminton, achieving remarkable success at inter‑school and state‑level competitions — a true testament to the school&#39;s unwavering commitment to holistic development, physical fitness, and sporting excellence.</span></p>\",\"subHeading\":\"\",\"achievements\":[{\"id\":\"ach‑1783515669201\",\"title\":\"Futsol 2024 Winner\",\"name\":\"Andres Iniesta\",\"designation\":\"Class 12‑D\",\"quote\":\"<p><strong class=\\\"ql-font-merriweather\\\">Andres Iniesta (Class XII‑D)</strong><span class=\\\"ql-font-merriweather\\\"> brought pride to</span><strong class=\\\"ql-font-merriweather\\\"> </strong><span class=\\\"ql-font-merriweather\\\">Malviya Convent School by winning the </span><strong class=\\\"ql-font-merriweather\\\">Football Trophy in 2024</strong><span class=\\\"ql-font-merriweather\\\"> through his outstanding performance, dedication, and sportsmanship. His achievement reflects the school&#39;s commitment to nurturing young sporting talent and encouraging students to pursue excellence both on and off the field. The MCS family congratulates Andres on this remarkable accomplishment and wishes him continued success in his football journey.</span></p>\",\"year\":\"2024\",\"category\":\"Sports\",\"photo\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783965715/school-saas/content/ocimbsbcct3ljgyip2m4.jpg\"},{\"id\":\"ach‑1783516095620\",\"title\":\"Chess Tournament\",\"name\":\"Carlo Ancelotti\",\"designation\":\"Class 8‑B\",\"quote\":\"<p><strong class=\\\"ql-font-playfair\\\">Carlo Ancelotti (Class VIII‑B)</strong><span class=\\\"ql-font-playfair\\\"> made Malviya Convent School proud by delivering an outstanding performance in the </span><strong class=\\\"ql-font-playfair\\\">Chess Tournament 2025</strong><span class=\\\"ql-font-playfair\\\">. Demonstrating exceptional strategic thinking, patience, and determination, Peter showcased remarkable skill throughout the competition and earned well‑deserved recognition for his achievement.</span></p>\",\"year\":\"2025\",\"category\":\"Sports\",\"photo\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783965784/school-saas/content/pcpfctr9ecoachzmoflu.jpg\"}],\"certifications\":[{\"id\":\"cert‑1783516265665\",\"image\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783516340/school-saas/content/ixbmmco53xbo1mx8qof9.webp\",\"title\":\"Chess Certificate\",\"info\":\"Anthony Bell won this tournament hard earned in 2009 \"},{\"id\":\"cert‑1783516372843\",\"image\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783516379/school-saas/content/dlsooiez5cg77ifg5izt.webp\",\"title\":\"Football Certificate\",\"info\":\"Philip won this tournament back in 2024 he is good at football he became the top scorer\"},{\"id\":\"cert‑1783516417201\",\"image\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783516423/school-saas/content/o79u4ywwsbyhr7n7ouqh.webp\",\"title\":\"Football Certifiacte 2020\",\"info\":\"Philip won this tournament back in 2024 he is good at football he became the top scorer\"},{\"id\":\"cert‑1783516430339\",\"image\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783965891/school-saas/content/vq9ac0lwy3zc2bdhvnt9.jpg\",\"title\":\"Football Certifiacte 2018\",\"info\":\"Philip won this tournament back in 2024 he is good at football he became the top scorer\"}],\"showSubHeading\":true,\"banner\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1783515585/school-saas/content/ffuewqpiqb3rzetyasew.jpg\",\"headingItalic\":false,\"headingColor\":\"#ffffff\",\"headingFont\":\"playfair\"}', 1, '2026-07-08 07:34:02', '2026-08-04 15:46:06');
