INSERT INTO `tbl_module_content` (`id`, `school_id`, `module_key`, `content`, `is_published`, `created_at`, `updated_at`) VALUES (1179, 9, 'testimonials', '{\"heading\":\"Testimonials\",\"testimonials\":[{\"id\":\"test‑1789366695701\",\"photo\":\"\",\"name\":\"Manyata Sharma\",\"type\":\"alumni\",\"role\":\"Parent of Grade 8th Student\",\"rating\":5,\"quote\":\"<p><span class=\\\"ql-font-playfair\\\">The teachers here genuinely care about every child. My daughter loves going to school every day! The teachers here genuinely care about every child. My daughter loves going to school every day! teachers here genuinely care about every child. My daughter loves going to school every day!</span></p>\"},{\"id\":\"test‑1786345623081\",\"photo\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1786345655/school-saas/content/azex9uhzpzxytjcouuop.jpg\",\"name\":\"Manyata Sharma\",\"type\":\"alumni\",\"role\":\"Parent of Grade 8th Student\",\"rating\":4,\"quote\":\"<p><span class=\\\"ql-font-playfair\\\">The teachers here genuinely care about every child. My daughter loves going to school every day!The teachers here genuinely care about every child. My daughter loves going to school every day!The teachers here genuinely care about every child. My daughter loves going to school every day!</span></p>\"},{\"id\":\"test‑1786344547844\",\"photo\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1786344878/school-saas/content/km2fdmdygrzj7hdfadq0.jpg\",\"name\":\"Anjali Sharma\",\"type\":\"parent\",\"role\":\"Parent of Grade 5 Student\",\"rating\":5,\"quote\":\"<p>The teachers here genuinely care about every child. My daughter loves going to school every day!</p>\"}],\"videoTestimonials\":[{\"id\":\"vtest‑1787160192779\",\"thumbnail\":\"https://res.cloudinary.com/dllspz9pv/image/upload/v1787160204/school-saas/content/pyrm4gpsmat1t6qhuk9h.jpg\",\"name\":\"ML\",\"type\":\"alumni\",\"role\":\"\",\"rating\":5,\"youtubeUrl\":\"https://youtu.be/c0E_lZzIw0w\"}],\"description\":\"<p>The teachers here genuinely care about every child. My daughter loves going to school every day!</p>\",\"headingFont\":\"playfair\"}', 1, '2026-08-10 01:29:31', '2026-09-14 00:49:02');
INSERT INTO `tbl_module_content` (`id`, `school_id`, `module_key`, `content`, `is_published`, `created_at`, `updated_at`) VALUES (1184, 9, 'admissionProcedure', '{\"heading\":\"How to Apply\",\"description\":\"<p>At <strong>Malviya Convent School</strong>, we value <strong>communication and engagement</strong>. Whether you’re a <strong>prospective parent, student, educator, or partner</strong>, our team is here to <strong>answer your queries, provide guidance, and assist you in any way possible</strong>.</p>\",\"formPdfUrl\":\"\",\"formLinkUrl\":\"https://www.subodhpublicschool.com/admin_uploads/web/viewer.html?file=Uploads/2026-27/Book%20List/BookList_Learners.pdf\",\"procedureBlocks\":[{\"id\":\"pb‑1786480751490\",\"heading\":\"Admission Procedure\",\"headingItalic\":false,\"headingColor\":\"\",\"headingFont\":\"\",\"headingSize\":\"\",\"description\":\"<p><strong class=\\\"ql-size-large ql-font-merriweather\\\">1. Admission Enquiry</strong></p><p><span class=\\\"ql-size-large ql-font-merriweather\\\"> Parents can begin the admission process by contacting the school or visiting the school campus to enquire about available seats, eligibility criteria, and the admission schedule.</span></p><p><strong class=\\\"ql-size-large ql-font-merriweather\\\">2. Registration / Application Form</strong></p><p><span class=\\\"ql-size-large ql-font-merriweather\\\"> Parents need to fill out the admission or registration form with the student’s basic information, date of birth, parent details, previous school information, and the class for which admission is being requested.</span></p><p><strong class=\\\"ql-size-large ql-font-merriweather\\\">3. Document Submission</strong></p><p><span class=\\\"ql-size-large ql-font-merriweather\\\"> The required documents may include the child’s birth certificate, Aadhaar card, recent passport‑size photographs, address proof, and previous academic records. For students transferring from another school, a Transfer Certificate may also be required. </span></p><p><strong class=\\\"ql-size-large ql-font-merriweather\\\">4. Assessment / Interaction</strong></p><p><span class=\\\"ql-size-large ql-font-merriweather\\\"> Depending on the class, the school may conduct an interaction or an assessment to understand the student’s academic level and suitability for the class.</span></p><p><strong class=\\\"ql-size-large ql-font-merriweather\\\">5. Selection and Confirmation</strong></p><p><span class=\\\"ql-size-large ql-font-merriweather\\\"> After reviewing the application, documents, and assessment/interview performance, the school will communicate the admission decision to the parents. Admission is subject to seat availability and school guidelines.</span></p><p><strong class=\\\"ql-size-large ql-font-merriweather\\\">6. Fee Submission</strong></p><p><span class=\\\"ql-size-large ql-font-merriweather\\\"> Once admission is confirmed, parents are required to complete the admission formalities and submit the applicable admission and tuition fees within the specified time.</span></p><p><strong class=\\\"ql-size-large ql-font-merriweather\\\">7. Final Admission</strong></p><p><span class=\\\"ql-size-large ql-font-merriweather\\\"> After successful completion of document verification and fee payment, the student’s admission is confirmed and the school provides information regarding the academic session, uniform, books, timetable, and other requirements.</span></p>\"}],\"steps\":[],\"headingFont\":\"montserrat\"}', 1, '2026-08-10 01:51:36', '2026-08-13 02:19:05');
